#define RVNPU_DDR_BYTES                      0x20000000
#define RVNPU_OPERAND_ALIGN                  0x00000008  /* A, B, C addresses */

/* Register offsets from RVNPU_MMIO_BASE (access type in the comment). */
#define RVNPU_MMIO_SHAPE_MN                  0x00000000  /* RW */
#define RVNPU_MMIO_SHAPE_K                   0x00000004  /* RW */
#define RVNPU_MMIO_ADDR_A                    0x00000008  /* RW */
