#define RVNPU_MMIO_FENCE                     0x0000001C  /* R */
#define RVNPU_MMIO_DONE                      0x00000020  /* W */
#define RVNPU_MMIO_DATA_BASE                 0x00000024  /* R */
#define RVNPU_MMIO_PROG_LEN                  0x00000028  /* R */

/* Shape fields. */
#define RVNPU_SHAPE_M_SHIFT                  0x00000000  /* in SHAPE_MN */
