#define RVNPU_SHAPE_N_SHIFT                  0x00000010  /* in SHAPE_MN */
#define RVNPU_SHAPE_N_MASK                   0x0000FFFF
#define RVNPU_SHAPE_K_SHIFT                  0x00000000  /* in SHAPE_K */
