/* STATUS and FENCE fields. */
#define RVNPU_STATUS_BUSY                    0x00000001
#define RVNPU_STATUS_ERROR                   0x00000002
#define RVNPU_STATUS_ERROR_CODE_SHIFT        0x00000008
#define RVNPU_STATUS_ERROR_CODE_MASK         0x000000FF
