/* Faults the MMIO block latches (STATUS error code, then ISA_ERROR). */
#define RVNPU_ERR_BAD_SHAPE                  0x00000011
#define RVNPU_ERR_MISALIGNED                 0x00000012
#define RVNPU_ERR_AXI_READ                   0x00000013
#define RVNPU_ERR_AXI_WRITE                  0x00000014

